extend schema
@link(
  url: "https://specs.apollo.dev/federation/v2.5"
  import: [
    "@authenticated"
    "@composeDirective"
    "@external"
    "@extends"
    "@inaccessible"
    "@interfaceObject"
    "@override"
    "@provides"
    "@key"
    "@requires"
    "@requiresScopes"
    "@shareable"
    "@tag"
