type Queries {
  productTypes: [Products!]! @listSize(assumedSize: 50)
  topSecretFederationFacts: [TopSecretFact!]! @requiresScopes(scopes: [["read:fact"], ["read:all"]])
  factTypes: [TopSecretFactType!]
